// 02-30_ascii-names.cjs - generated by zemory hook guard (plan/27). Settings: policy.json.
"use strict";
const fs = require("node:fs");
const path = require("node:path");

const BT = String.fromCharCode(96);
const relOf = (root, abs) => path.relative(root, path.resolve(root, abs)).replace(/\\/g, "/");
const inside = (rel) => rel && !rel.startsWith("..") && !path.isAbsolute(rel);

// What the call ADDS and REMOVES for a file tool; newLines = added lines not already present (multiset, trimmed).
function edit(payload, root) {
  const tool = payload.tool_name || "";
  const ti = payload.tool_input || {};
  const abs = ti.file_path || ti.notebook_path || "";
  if (!abs || !["Write", "Edit", "MultiEdit", "NotebookEdit"].includes(tool)) return null;
  const rel = relOf(root, abs);
  if (!inside(rel)) return null;
  let added = "", removed = "", exists = false;
  try { exists = fs.existsSync(abs); } catch { exists = false; }
  if (tool === "Write") {
    added = String(ti.content || "");
    try { removed = exists ? fs.readFileSync(abs, "utf8") : ""; } catch { removed = ""; }
  } else if (tool === "Edit") {
    added = String(ti.new_string || ""); removed = String(ti.old_string || "");
  } else if (tool === "MultiEdit") {
    for (const e of ti.edits || []) { added += "\n" + (e.new_string || ""); removed += "\n" + (e.old_string || ""); }
  } else {
    added = String(ti.new_source || "");
  }
  const seen = new Map();
  for (const l of removed.split(/\r?\n/)) { const k = l.trim(); if (k) seen.set(k, (seen.get(k) || 0) + 1); }
  const newLines = [];
  for (const l of added.split(/\r?\n/)) {
    const k = l.trim();
    if (!k) continue;
    const n = seen.get(k) || 0;
    if (n > 0) seen.set(k, n - 1); else newLines.push(l);
  }
  return { tool, abs, rel, added, removed, exists, newLines };
}

// The rule's own text, capped. Folder harness (plan/28 §0d): the body of RULE.md beside this hook. File harness: the line
// carrying its number in the rules file plus its continuation lines.
function ownRule(root) {
  try {
    const file = path.join(__dirname, "RULE.md");
    let lines = fs.readFileSync(file, "utf8").split(/\r?\n/);
    if (lines[0] === "---") lines = lines.slice(lines.indexOf("---", 1) + 1);
    const body = lines.filter((l, i) => i > 0 || l.trim()).slice(0, 20).map((l) => (l.length > 400 ? l.slice(0, 400) + "…" : l));
    return { rel: path.relative(root, file).replace(/\\/g, "/"), text: body.join("\n").trim() };
  } catch {
    return null;
  }
}
function ruleText(root, file, id) {
  try {
    const lines = fs.readFileSync(path.join(root, file), "utf8").split(/\r?\n/);
    const at = lines.findIndex((l) => l.includes(BT + id + BT) || l.startsWith(id + " "));
    if (at < 0) return "";
    const out = [lines[at]];
    for (let i = at + 1; i < lines.length && out.length < 12; i++) {
      const l = lines[i];
      if (!l.trim() || /^(- |#|\x60\x60\x60|\d{2}-\d+ |<!--)/.test(l)) break;
      out.push(l);
    }
    return out.map((l) => (l.length > 400 ? l.slice(0, 400) + "…" : l)).join("\n");
  } catch {
    return "";
  }
}
// The citation: a hook inside a renamed rule folder (plan/28 §0o) cites the folder's full name, which is always the rule's
// current name; a legacy folder or the file harness keeps "rule <id>".
function citation(id) {
  const folder = path.basename(__dirname);
  return /^(Rule|Cons)_(Gate|Keys|Core)_\d+_/.test(folder) ? folder : "rule " + id;
}
function blocked(root, policy, id, what) {
  const own = ownRule(root);
  if (own && own.text) return "BLOCKED (guard layer 1): " + citation(id) + " - " + what + "\n\nThe rule (" + own.rel + "):\n" + own.text;
  const text = ruleText(root, policy.rules_file || "", id);
  return "BLOCKED (guard layer 1): rule " + id + " - " + what + (text ? "\n\nThe rule (" + policy.rules_file + "):\n" + text : "");
}

// A DOOR reminder for a rule that cannot be forbidden, only recalled at the right moment: the FIRST matching call of a
// session is blocked with the rule; the same call retried passes. Remembered per session in <hooks>/.seen.json (git-ignored,
// last 50 sessions). No session id to remember by => never block (fail-open).
function remindOnce(payload, root, policy, key) {
  const sid = String(payload.session_id || payload.transcript_path || "");
  if (!sid) return false;
  const file = path.join(root, policy.flags_dir || "docs/hooks", ".seen.json");
  let all = {};
  try { all = JSON.parse(fs.readFileSync(file, "utf8")) || {}; } catch { all = {}; }
  const list = Array.isArray(all[sid]) ? all[sid] : [];
  if (list.includes(key)) return false;
  all[sid] = list.concat(key);
  const keys = Object.keys(all);
  for (const k of keys.slice(0, Math.max(0, keys.length - 50))) delete all[k];
  try { fs.writeFileSync(file, JSON.stringify(all)); } catch { return false; }
  return true;
}
const ONCE = "\nThis is a reminder, shown once per session: retry the same call to continue.";

// Paths the language rules do not reach: other people's code, frozen hand-overs, deliberate ASCII samples.
// The write-docx reference samples sit under .claude/skills/ in a repo and under _Store/04_SKILLS/ in the parts store.
const LANG_EXEMPT = [/(^|\/)external\//, /(^|\/)attic\//, /(^|\/)(skills|04_SKILLS)\/write-docx\/reference\//];
const CODE_EXT = /\.(ts|tsx|js|jsx|mjs|cjs|py)$/i;

const VI_ONSET = /^(ngh|ng|nh|ch|gh|gi|kh|ph|th|tr|qu|b|c|d|g|h|k|l|m|n|p|r|s|t|v|x)?/;
const VI_RHYME = new Set(("a ai ao au ay an ang anh ac ach am ap at " +
  "e eo em en eng ep et ec ech enh " +
  "i ia iu ieu iem ien ieng iep iet iec inh ich im in ip it " +
  "o oa oai oan oang oanh oac oach oam oap oat oay oe oen oeo oet oi om on ong oong oc op ot " +
  "u ua uan uang uat uay ue uen uet ui um un ung uc up ut uy uya uyen uyet uynh uych uyu uoi uom uon uong uoc uop uot uou " +
  "ui ung uu uoi").split(" "));
const VI_EN = new Set(["a", "an", "at", "be", "can", "do", "go", "he", "in", "is", "it", "me", "no", "on", "so", "to", "up",
  "we", "man", "ban", "bat", "bin", "map", "mat", "net", "pin", "set", "tin", "top", "van", "hot", "hit", "kit", "lot",
  "not", "pot", "sit", "tag", "tab", "cap", "cat", "cut", "gap", "hat", "nut", "pan", "pat", "pet", "tap", "ten", "tip",
  "con", "den", "hen", "pen", "sun", "run", "gun", "bun", "fun", "mug", "rug", "bug", "hub", "sub", "tub", "cup"]);
function viSyllable(w) {
  const rest = w.replace(VI_ONSET, "");
  return rest !== w || /^[aeiouy]/.test(w) ? VI_RHYME.has(rest) : false;
}
// Short programming words (get · set · map · put · lang · vec) also fit the syllable shape, so fitting is not enough:
// at least one part must carry a mark English names lack — a Vietnamese-only rhyme, a Vietnamese-only onset, or one of
// the unmistakable words rule 30 already uses. Measured on zemory's 920 file names and 20,370 identifiers.
const VI_RHYME_ONLY = new Set(("ieu iem ien ieng iep iet iec ia iu uong uon uoc uot uoi uom uop uou uyen uyet uynh uych uya uyu uy " +
  "oai oan oang oanh oac oach oam oap oat oay oe oen oeo oet oong ao au uu inh ich anh ach enh ech ua").split(" "));
const VI_WORD = new Set(["khong", "duoc", "nguoi", "viec", "tieng", "nhieu", "truong", "thuong", "phuong", "huong", "duong",
  "luong", "tuong", "chuong", "muon", "ket", "thiet", "dien", "diem", "kiem", "hien", "chuyen", "quyen", "tuyen", "nguon",
  "thuoc", "buoc", "cuoc", "nuoc", "truoc", "suot", "luot", "doan", "loai", "ngoai", "xuat", "mot", "cua", "cho", "voi"]);
function viMarked(w) {
  if (VI_WORD.has(w)) return true;
  if (/^(ngh|ng|nh|kh|gh)/.test(w)) return true;
  return VI_RHYME_ONLY.has(w.replace(VI_ONSET, ""));
}
function viWords(text) {
  const parts = String(text).replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .split(/[^A-Za-z]+/).filter(Boolean).map((w) => w.toLowerCase());
  if (parts.length < 2 || !parts.every(viSyllable)) return null;
  if (parts.every((p) => VI_EN.has(p))) return null;
  if (!parts.some(viMarked)) return null;
  return parts.join(" ");
}
// null = an English (or neutral) name · string = the Vietnamese words. A name of components joined by "_"
// (Rule_Core_80_DieuMotBatBien) is judged component by component as well as whole.
function viName(name) {
  const base = String(name).replace(/\.[A-Za-z0-9]+$/, "");
  for (const c of [base, ...base.split("_")]) {
    const hit = viWords(c);
    if (hit) return hit;
  }
  return null;
}

const DECL = /(?:const|let|var|function|class|interface|type|enum|def)\s+([A-Za-z_$À-￿][\w$À-￿]*)/g;
const ID_A = new Set(["khong", "duoc", "nguoi", "viec", "tieng", "nhieu", "truong", "thuong", "phuong", "huong", "duong",
  "luong", "tuong", "chuong", "muon", "ket", "thiet", "dien", "diem", "kiem", "hien", "chuyen", "quyen", "tuyen", "nguon",
  "thuoc", "buoc", "cuoc", "nuoc", "truoc", "suot", "luot", "doan", "loai", "ngoai", "xuat"]);
const parts = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1 $2").split(/[^A-Za-z]+/).filter(Boolean).map((w) => w.toLowerCase());
function strip(src, py) {
  if (py) src = src.replace(/#[^\n]*/g, " ");
  return src.replace(/\/\*[\s\S]*?\*\//g, " ").replace(/(^|[^:])\/\/[^\n]*/g, "$1 ")
    .replace(new RegExp(BT + "(?:\\\\[\\s\\S]|[^" + BT + "\\\\])*" + BT, "g"), " ")
    .replace(/'(?:\\[\s\S]|[^'\\\n])*'/g, " ").replace(/"(?:\\[\s\S]|[^"\\\n])*"/g, " ");
}
const NEW_DIR = /^(mkdir|md|new-item|ni|touch)$/i;
function check(payload, root, policy) {
  try {
    const ti = payload.tool_input || {};
    if (typeof ti.command === "string" && ti.command) {
      for (const seg of ti.command.split(/[\n;&|]+/)) {
        const toks = seg.trim().split(/\s+/);
        if (!toks.length || !NEW_DIR.test(toks[0].replace(/^.*[\\/]/, ""))) continue;
        for (const t of toks.slice(1)) {
          const tok = t.replace(/^["']|["']$/g, "");
          if (!tok || tok.startsWith("-")) continue;
          const last = tok.replace(/[\\/]+$/, "").split(/[\\/]/).pop() || "";
          const vi = viName(last);
          if (!/[^\x20-\x7E]/.test(tok) && !vi) continue;
          if (!inside(relOf(root, tok))) continue;
          return blocked(root, policy, "02-30", "creating " + tok + " - a file or folder name in the repo is ASCII English" +
            (vi ? " ('" + last + "' reads as Vietnamese without marks: " + vi + ")" : "") + ".");
        }
      }
      return null;
    }
    const e = edit(payload, root);
    if (!e) return null;
    // Names first: the exemption below is for the CONTENT of harness files (written in Vietnamese), never for the name of
    // a new file or folder — a rule folder named in Vietnamese without marks slipped through it.
    if (!e.exists) {
      const bad = e.rel.split("/").find((p) => /[^\x20-\x7E]/.test(p));
      if (bad) return blocked(root, policy, "02-30", "creating " + e.rel + " - the name part '" + bad + "' is not ASCII English.");
      const vi = e.rel.split("/").map((p) => [p, viName(p)]).find(([, v]) => v);
      if (vi) return blocked(root, policy, "02-30", "creating " + e.rel + " - the name part '" + vi[0] + "' reads as Vietnamese without marks (" + vi[1] + "); names are English.");
    }
    if (LANG_EXEMPT.some((re) => re.test(e.rel))) return null;
    if (!CODE_EXT.test(e.rel)) return null;
    const code = strip(e.newLines.join("\n"), /\.py$/i.test(e.rel));
    const hits = [];
    for (const m of code.matchAll(DECL)) {
      const name = m[1];
      if (/[^\x00-\x7F]/.test(name)) hits.push(name + " (non-ASCII)");
      else {
        const v = parts(name).filter((w) => ID_A.has(w));
        const vn = viName(name);
        if (v.length) hits.push(name + " (" + v.join(",") + ")");
        else if (vn) hits.push(name + " (" + vn + ")");
      }
    }
    if (!hits.length) return null;
    return blocked(root, policy, "02-30", "new identifier(s) in " + e.rel + " that are not ASCII English: " + hits.slice(0, 5).join(" · ") +
      ". Everything in code is English, comments included.");
  } catch { return null; }
}
module.exports = { check };
